catalog_script_client.script:
function onLoad() {
    g_form.setValue('wu_location', '9437ae841b3135989fde86acdd4bcb9b'); //default to flu walkup location
    //g_form.setValue('reason', '0a31be2487ee155050d2eca73cbb3517');
    if (g_form.getValue('is_allowed_to_book_for_others') === "true") {
        var ga = new GlideAjax('x_hccc_hoc_ohs.HoCOHSMFluClinicAjax');

        ga.addParam('sysparm_name', 'getUserType');
        ga.getXML(function(response) {
            var answer = response.responseXML.documentElement.getAttribute('answer');

            //g_form.addErrorMessage("user type: " + answer);
            switch (answer) {
                case "admin":
                    /*
					hoc admin that have access to select others 
					are allowed that because of roles (such as technician or advisor) instead of user type.
					As such we do not remove options as those technicians are supposed to be able to book for everyone
					*/
                    break;
                case "mp_staff": //mp_staff should be able to book for MPs
                    g_form.removeOption('who_are_you_booking_for', 'internal');
                    g_form.removeOption('who_are_you_booking_for', 'pps');
                    break;
                case "pps": //pps should be able to book for pps
                    g_form.removeOption('who_are_you_booking_for', 'internal');
                    g_form.removeOption('who_are_you_booking_for', 'mp');
                    //g_form.removeOption('who_are_you_booking_for', 'external');
                    break;
                default:
            }
        });
    } else {
        g_form.setValue('who_are_you_booking_for', 'myself');
    }


}
